import Foundation

/// Per-adapter command definitions for the machine-readable registry.
extension CommandRegistry {

    static let agent = group(name: "agent", description: "Global discovery commands for people, scripts, and agents.", usage: "mpia --help | mpia manifest --format json | mpia --version", subcommands: [
        leaf(name: "help", description: "Print global or adapter help. This is human-readable; use manifest for the machine-readable command contract.", usage: "mpia --help"),
        leaf(name: "manifest", description: "Return the complete machine-readable command registry, safety metadata, exit codes, and JSON schemas under data.schemas.", usage: "mpia manifest --format json"),
        leaf(name: "version", description: "Print the CLI release version; -v is an equivalent shorthand.", usage: "mpia --version"),
    ])

    static let resources = leaf(
        name: "resources",
        description: "Discover every macOS data resource the CLI can access (Contacts, Mail, Calendar, Reminders, Photos, Notes, Shortcuts, Safari, Messages, and Call History), with selection state, authorization status, and read/write capabilities. Read-only; never prompts for permission.",
        usage: "mpia resources --format json",
        outputSchema: "DataResourcesResult"
    )

    static let contacts = group(name: "contacts", description: "Query and manage contacts.", subcommands: [
        leaf(name: "permission", description: "Report the current Contacts authorization status without prompting. Read-only; grant or revoke access in System Settings → Privacy & Security → Contacts.", usage: "mpia contacts permission", exitCodes: contactsExit),
        leaf(name: "containers", description: "List the available Contacts containers and mark which one is the selected iCloud container. Read-only.", usage: "mpia contacts containers", exitCodes: contactsExit),
        leaf(name: "container", description: "Show the currently selected Contacts container (identifier, type, and iCloud flag). Read-only.", usage: "mpia contacts container", exitCodes: contactsExit,
        outputSchema: "ContactContainer"),
        leaf(name: "count", description: "Return the total number of contacts in the selected (iCloud) container. Read-only.", usage: "mpia contacts count [--format json]", exitCodes: contactsExit),
        leaf(name: "list", description: "List contacts from the selected container with cursor pagination. Read-only; page size defaults to 50.", usage: "mpia contacts list --format json",
             params: [int("limit", "Page size", default: "50"), string("cursor", "Opaque cursor")], exitCodes: contactsExit,
             outputSchema: "Page"),
        leaf(name: "get", description: "Fetch one contact by its stable external ID. Ambiguous or missing matches are reported, never silently resolved. Read-only.", usage: "mpia contacts get --external-id <id> --format json",
             params: [string("external-id", "External ID", required: true)], exitCodes: [contactsExit, queryExit].flatMap { $0 },
             outputSchema: "ContactPayload"),
        leaf(name: "query", description: "Query contacts by up to three AND-combined filters (name, email, phone, organization, postal code, or kind). Read-only.", usage: "mpia contacts query [filters] --format json",
             params: [string("name", "Name filter"), string("email", "Email filter"), string("phone", "Phone filter"),
                      string("organization", "Organization filter"), string("postal-code", "Postal code filter"), string("kind", "person|organization")],
             exitCodes: [contactsExit, queryExit].flatMap { $0 }, outputSchema: "Page"),
        leaf(name: "create", description: "Create a contact in the verified iCloud container. Requires --dry-run (preview) or --apply (persist); every created contact must carry a unique external_id.", usage: "mpia contacts create --input <file>|--stdin --dry-run|--apply [--idempotent]",
             mutates: true, params: [string("input", "JSON file", type: .file), bool("stdin", "Read JSON from stdin"),
                                     bool("apply", "Persist (else dry-run)"), bool("idempotent", "Opt-in create retry")],
             exitCodes: contactsExit, safety: dryRunApply, inputSchema: "ContactPayload", outputSchema: "ContactWriteResult"),
        leaf(name: "edit", description: "Apply a partial edit to a contact identified by external_id; omitted fields are preserved. Requires --dry-run or --apply.", usage: "mpia contacts edit --external-id <id> --input <file>|--stdin --dry-run|--apply",
             mutates: true, params: [string("external-id", "External ID", required: true), string("input", "JSON file", type: .file),
                                     bool("stdin", "Read JSON from stdin")], exitCodes: [contactsExit, queryExit].flatMap { $0 }, safety: dryRunApply,
             inputSchema: "ContactPatch"),
        leaf(name: "avatar verify", description: "Check whether a contact's avatar can be read back, returning a tri-state result (readback_confirmed, not_available, or verification_unknown). Read-only.", usage: "mpia contacts avatar verify --external-id <id> --format json",
             params: [string("external-id", "External ID", required: true)], exitCodes: [contactsExit, queryExit].flatMap { $0 },
             outputSchema: "AvatarWriteVerification"),
        leaf(name: "avatar replace", description: "Replace a contact's avatar image. Requires --apply and the exact confirmation phrase \"RECREATE CONTACT\".", usage: "mpia contacts avatar replace --external-id <id> --image <file> --apply --confirm \"RECREATE CONTACT\"",
             mutates: true, params: [string("external-id", "External ID", required: true), string("image", "Image file", type: .file)],
             exitCodes: [contactsExit, queryExit].flatMap { $0 }, safety: avatarReplace),
        leaf(name: "delete", description: "Delete a contact by external_id. Requires --apply and the exact confirmation phrase \"DELETE CONTACT\".", usage: "mpia contacts delete --external-id <id> --apply --confirm \"DELETE CONTACT\"",
             mutates: true, params: [string("external-id", "External ID", required: true), bool("ignore-not-found", "Opt-in delete retry")],
             exitCodes: [contactsExit, queryExit].flatMap { $0 }, safety: deleteContact),
        leaf(name: "external-id migrate", description: "Change a contact's external ID from one value to another. Requires --apply and the exact confirmation phrase \"CHANGE EXTERNAL ID\".", usage: "mpia contacts external-id migrate --from <old> --to <new> --apply --confirm \"CHANGE EXTERNAL ID\"",
             mutates: true, params: [string("from", "Old external ID", required: true), string("to", "New external ID", required: true)],
             exitCodes: [contactsExit, queryExit].flatMap { $0 }, safety: migrateContact),
        leaf(name: "export", description: "Export a full JSON snapshot of the contacts in the selected container. Read-only; optionally write to a file with --output.", usage: "mpia contacts export --format json [--output <file>]",
             params: [string("output", "Output file", type: .file)], exitCodes: contactsExit),
    ])

    static let mail = group(name: "mail", description: "Read-only Mail access over the local SQLite store with a bounded Apple Events fallback.", subcommands: [
        leaf(name: "doctor", description: "Probe the Mail store and capability status (SQLite fast-path availability, fallback, and permission state). Read-only; run before relying on direct-store reads.", usage: "mpia mail doctor --format json", exitCodes: mailExit),
        leaf(name: "accounts", description: "List mail accounts discovered in the local store. Read-only; account IDs are opaque adapter values.", usage: "mpia mail accounts --format json", exitCodes: mailExit, outputSchema: "ListResult"),
        leaf(name: "mailboxes", description: "List mailboxes, optionally scoped to one account by opaque ID. Read-only.", usage: "mpia mail mailboxes [--account-id <id>] --format json",
             params: [string("account-id", "Account ID")], exitCodes: mailExit, outputSchema: "ListResult"),
        leaf(name: "threads", description: "List message threads with bounded pagination. Read-only; default limit 50, max 200.", usage: "mpia mail threads --format json", params: [int("limit", "Page size")], exitCodes: mailExit, outputSchema: "Page"),
        leaf(name: "query", description: "Query message metadata with bounded cursor pagination. Read-only; never reads message bodies.", usage: "mpia mail query [filters] [--limit <n>] [--cursor <c>] --format json",
             params: [int("limit", "Page size", default: "50"), string("cursor", "Opaque cursor")], exitCodes: mailExit,
             outputSchema: "MailQueryResult"),
        leaf(name: "search", description: "Full-text search cached message text under a one-second budget, scanning at most 200 candidates. Read-only.", usage: "mpia mail search <text> --format json",
             params: [string("text", "Search text", required: true)], exitCodes: mailExit),
        leaf(name: "get", description: "Fetch one message by opaque ID. Defaults to metadata; --content text reads a bounded plain-text projection and --content raw writes RFC 822 to a file, never into JSON.", usage: "mpia mail get --id <id> [--content metadata|text|raw] --format json",
             params: [string("id", "Message ID", required: true), string("content", "metadata|text|raw")], exitCodes: mailExit,
             outputSchema: "MailMessageMetadata"),
        leaf(name: "reveal", description: "Reveal one message visibly in Mail.app. An explicit visible operation that may launch and activate Mail.app.", usage: "mpia mail reveal --id <id> --format json",
             params: [string("id", "Message ID", required: true)], exitCodes: mailExit),
        leaf(name: "attachments verify", description: "Compare SQLite row counts with cached MIME part counts for one message. Read-only; never returns attachment names or paths.", usage: "mpia mail attachments verify --id <id> --format json",
             params: [string("id", "Message ID", required: true)], exitCodes: mailExit),
        leaf(name: "attachments export", description: "Export cached attachments for one message to a directory. Refuses overwrite and never writes bytes to JSON or stdout.", usage: "mpia mail attachments export --id <id> --output <dir>",
             params: [string("id", "Message ID", required: true), string("output", "Output directory", type: .file)], exitCodes: mailExit),
    ])

    static let calendar = group(name: "calendar", description: "Query and manage calendar events in the uniquely verified iCloud CalDAV source.", subcommands: [
        leaf(name: "permission", description: "Report Calendar full-access authorization status. Read-only; write-only access is not readable.", usage: "mpia calendar permission", exitCodes: calendarExit),
        leaf(name: "sources", description: "List EventKit sources and mark the selected iCloud CalDAV source. Read-only.", usage: "mpia calendar sources --format json", exitCodes: calendarExit, outputSchema: "ListResult"),
        leaf(name: "calendars", description: "List calendars in the selected iCloud source. Read-only.", usage: "mpia calendar calendars --format json", exitCodes: calendarExit, outputSchema: "ListResult"),
        leaf(name: "query", description: "Query events in a bounded range (start before end, at most 366 days). Read-only; default limit 50, max 200.", usage: "mpia calendar query --start <iso> --end <iso> --format json",
             params: [string("start", "Start ISO 8601", required: true), string("end", "End ISO 8601", required: true)], exitCodes: calendarExit,
             outputSchema: "Page"),
        leaf(name: "conflicts", description: "Scan event-time overlaps in a range, treating adjacent boundaries as non-conflicting (max 200 events). Read-only.", usage: "mpia calendar conflicts --start <iso> --end <iso> --format json",
             params: [string("start", "Start ISO 8601", required: true), string("end", "End ISO 8601", required: true)], exitCodes: calendarExit),
        leaf(name: "get", description: "Fetch one event by opaque ID. Read-only.", usage: "mpia calendar get --id <id> --format json",
             params: [string("id", "Event ID", required: true)], exitCodes: calendarExit,
             outputSchema: "CalendarEventPayload"),
        leaf(name: "create", description: "Create an event in an iCloud calendar. Requires --dry-run or --apply; returns the created payload.", usage: "mpia calendar create --input event.json --dry-run|--apply",
             mutates: true, params: [string("input", "JSON file", type: .file)], exitCodes: calendarExit, safety: dryRunApply,
             inputSchema: "CalendarEventInput", outputSchema: "CalendarEventPayload"),
        leaf(name: "edit", description: "Partially edit an event by opaque ID. Requires --dry-run or --apply; recurring edits require --span this|future.", usage: "mpia calendar edit --id <id> --input patch.json --dry-run|--apply",
             mutates: true, params: [string("id", "Event ID", required: true), string("input", "JSON file", type: .file)], exitCodes: calendarExit, safety: dryRunApply,
             inputSchema: "CalendarEventPatch"),
        leaf(name: "delete", description: "Delete an event by opaque ID. Requires --apply and --confirm \"DELETE EVENT\"; recurring deletes require --span this|future.", usage: "mpia calendar delete --id <id> --apply --confirm \"DELETE EVENT\"",
             mutates: true, params: [string("id", "Event ID", required: true)], exitCodes: calendarExit, safety: deleteEvent),
    ])

    static let reminders = group(name: "reminders", description: "Query and manage reminders in the uniquely verified iCloud CalDAV source.", subcommands: [
