        leaf(name: "create", description: "Create a reminder in a writable iCloud list. Requires --dry-run or --apply; returns read-back verification.", usage: "mpia reminders create --input reminder.json --dry-run|--apply",
             mutates: true, params: [string("input", "JSON file", type: .file)], exitCodes: remindersExit, safety: dryRunApply,
