    ])

    static let photos = group(name: "photos", description: "Query photo metadata and export via public PhotoKit.", subcommands: [
        leaf(name: "permission", description: "Report Photos authorization status without prompting. Read-only; use --request to explicitly prompt.", usage: "mpia photos permission", params: [bool("request", "Explicitly request Photos authorization")], exitCodes: photosExit),
